detaileddescription.para:
Using a selector is simple: 

populate the selector with all the sockets that you want to observe 


make it wait until there is data available or data can be sent on any of the sockets 


test each socket to find out which ones are ready for receiving or sending


If scalability is a concern, using callbacks is also possible: 

add all the sockets that you want to observe to the selector with their own ready callbacks 


make the selector wait until there is data available or data can be sent on any of the sockets 


dispatch the callbacks of the sockets that became ready during the wait


Usage example: //Createasockettolistentonewconnections
sf::TcpListenerlistener;
if(listener.listen(55001)!=sf::Socket::Status::Done)
{
//Handleerror...
}

//Createalisttostorethefutureclients
std::vector<sf::TcpSocket>clients;

//Createaselector
sf::SocketSelectorselector;

//Addthelistenertotheselector
selector.add(listener);

//Endlessloopthatwaitsfornewconnections
while(running)
{
//Maketheselectorwaitfordataonanysocket
if(selector.wait())
{
//Testthelistener
if(selector.isReady(listener))
{
//Thelistenerisready:thereisapendingconnection
sf::TcpSocketclient;
if(listener.accept(client)==sf::Socket::Status::Done)
{
//Addthenewclienttotheselectorsothatwewill
//benotifiedwhentheysendsomething
selector.add(client);

//Addthenewclienttotheclientslist
clients.push_back(std::move(client));
}
else
{
//Handleerror...
}
}
else
{
//Thelistenersocketisnotready,testallothersockets(theclients)
for(sf::TcpSocket&client:clients)
{
if(selector.isReady(client))
{
//Theclienthassentsomedata,wecanreceiveit
sf::Packetpacket;
if(client.receive(packet)==sf::Socket::Status::Done)
{
...
}
}
}
}
}
}

Usage example with callbacks: //Createasockettolistentonewconnections
sf::TcpListenerlistener;
if(listener.listen(55001)!=sf::Socket::Status::Done)
{
//Handleerror...
}

//Createalisttostorethefutureclients
//Weuseastd::listherebecausemodifications
//don'tinvalidatereferencestoexistingelements
std::list<sf::TcpSocket>clients;

//Createaselector
sf::SocketSelectorselector;

//Listenerscanonlybecomereadytoreceivesowedon't
//havetocheckthereadinesstypeintheircallback
constautolistenerCallback=[&](sf::SocketSelector::ReadinessType)
{
//Thelistenerisready:thereisapendingconnection
sf::TcpSocketnewSocket;
if(listener.accept(newSocket)==sf::Socket::Status::Done)
{
//Addthenewclienttotheclientslist
auto&client=clients.emplace_back(std::move(newSocket));

constautoclientCallback=[&client](sf::SocketSelector::ReadinessTypereadinessType)
{
if(readinessType&sf::SocketSelector::Receive)
{
//Theclienthassentsomedata,wecanreceiveit
sf::Packetpacket;
if(client.receive(packet)==sf::Socket::Status::Done)
{
...
}
}
};

//Addthenewclienttotheselectorwithanattached
//callbackthatwillbecalledwhentheysendsomething
selector.add(client,sf::SocketSelector::Receive,clientCallback);
}
else
{
//Handleerror...
}
};

//Addthelistenertotheselectorwithanattachedcallback
selector.add(listener,sf::SocketSelector::Receive,listenerCallback);

//Endlessloopthatwaitsfornewconnectionsandreceivesclientdata
while(running)
{
//Maketheselectorwaitforsocketstobecomereadyanddispatchtheircallbacks
if(selector.wait())
selector.dispatchReadyCallbacks();
}
